// Valida la petición de reserva. Contrato: n8n/WEB-RESERVAS.md.
const hook = $('Webhook · POST /web-reservar').first().json;
const VENTANA_MS = 60 * 60 * 1000;
const MAXIMO = 5;

const cfg = $('Config (editar por tenant)').first().json;
const tz = cfg.tenant_timezone || 'Europe/Madrid';
const headers = hook.headers || {};
const fallo = (http, motivo, extra = {}) =>
  [{ json: { _ok: false, _http: http, body: { ok: false, motivo, ...extra } } }];

// Origen permitido: ajuste WEB_ORIGENES del tenant (el de desarrollo añade el servidor
// local de Astro). Este 403 es lo que hace cumplir la regla; el CORS del webhook va abierto.
const ORIGENES = String(cfg.origenes_web || '').split(',').map(s => s.trim()).filter(Boolean);
const origen = String(headers.origin || '').trim();
if (!ORIGENES.includes(origen)) return fallo(403, 'origen_no_permitido');

// Límite por IP, en los datos estáticos del workflow (solo persisten en ejecuciones de
// producción, no al probar desde el editor). La IP es la primera de X-Forwarded-For: la
// pone Caddy, que no se fía de la que mande el cliente.
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'desconocida').split(',')[0].trim();
let _limite = 'activo';
try {
  const sd = $getWorkflowStaticData('global');
  const ahora = Date.now();
  const rl = sd.rl || {};
  for (const k of Object.keys(rl)) {
    rl[k] = rl[k].filter(t => ahora - t < VENTANA_MS);
    if (!rl[k].length) delete rl[k];
  }
  const marcas = rl[ip] || [];
  if (marcas.length >= MAXIMO) { sd.rl = rl; return fallo(429, 'demasiadas_peticiones'); }
  marcas.push(ahora);
  rl[ip] = marcas;
  sd.rl = rl;
} catch (e) {
  // Si los datos estáticos no estuvieran disponibles, la petición sigue pero queda a la
  // vista en la ejecución: una protección que no se ve no está funcionando.
  _limite = 'NO DISPONIBLE: ' + (e && e.message ? e.message : String(e));
}

const b = hook.body || {};
const txt = v => (v === undefined || v === null) ? '' : String(v).trim();
const campos = {};

const inicio = txt(b.inicio);
const dt = DateTime.fromISO(inicio, { setZone: true });
if (!inicio) campos.inicio = 'obligatorio';
else if (!dt.isValid || !/(Z|[+-]\d{2}:?\d{2})$/.test(inicio)) campos.inicio = 'formato';

const nombre = txt(b.nombre);
if (!nombre) campos.nombre = 'obligatorio';
else if (nombre.length < 2 || nombre.length > 100) campos.nombre = 'largo';

const email = txt(b.email).toLowerCase();
if (!email) campos.email = 'obligatorio';
else if (email.length > 254) campos.email = 'largo';
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) campos.email = 'formato';

// E.164 sin '+', igual que el resto de la plataforma (WhatsApp lo entrega así), para que
// quien reserva por la web y luego escribe por WhatsApp sea el mismo contacto.
// 9 dígitos que empiezan por 6/7/8/9 son españoles; si no, tiene que venir con prefijo.
const telCrudo = txt(b.telefono);
let telefono = '';
if (!telCrudo) campos.telefono = 'obligatorio';
else {
  const digitos = telCrudo.replace(/[^\d]/g, '');
  if (/^[6789]\d{8}$/.test(digitos)) telefono = '34' + digitos;
  else if (/^(\+|00)/.test(telCrudo)) {
    const sinCero = digitos.replace(/^00/, '');
    if (sinCero.length >= 8 && sinCero.length <= 15) telefono = sinCero;
  }
  if (!telefono) campos.telefono = 'formato';
}

const empresa = txt(b.empresa);
if (empresa.length > 120) campos.empresa = 'largo';
const mensaje = txt(b.mensaje);
if (mensaje.length > 1000) campos.mensaje = 'largo';

const id = txt(b.id_solicitud).toLowerCase();
if (!id) campos.id_solicitud = 'obligatorio';
else if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) campos.id_solicitud = 'formato';

if (Object.keys(campos).length) return fallo(400, 'datos_invalidos', { campos });

// Campo trampa: una persona no lo ve y lo deja vacío. Se sigue adelante para contestar
// lo mismo que a una reserva buena, pero `Code · Preparar` no reserva nada.
const trampa = txt(b.sitio_web) !== '';
return [{ json: { _ok: true, _limite, ip, trampa, inicio, nombre, email, telefono, empresa,
  mensaje, id_solicitud: id, tz } }];

// Servicio resuelto -> lo que va a la reserva, y la cita tal y como se le enseña a la web.
const v = $('Code · Validar').first().json;
const r = $json ?? {};
const filas = (r.body && r.body.data) || [];
if ((r.statusCode ?? 0) >= 300 || filas.length !== 1) {
  return [{ json: { _reservar: false, _http: 503, body: { ok: false, motivo: 'no_disponible' },
    _causa: filas.length > 1 ? 'hay varios servicios activos con ese nombre'
                             : 'servicio no encontrado o Directus no responde' } }];
}
const s = filas[0];
const dt = DateTime.fromISO(v.inicio, { setZone: true }).setZone(v.tz);
const cita = {
  inicio: v.inicio,
  fecha_label: dt.setLocale('es').toFormat("cccc d 'de' LLLL"),
  hora: dt.toFormat('HH:mm'),
  duracion_minutos: s.duration_minutes,
  servicio: s.name,
};
if (v.trampa) {
  return [{ json: { _reservar: false, _http: 200, body: { ok: true, motivo: 'reservada', cita },
    _trampa: 'campo sitio_web relleno: no se ha reservado nada' } }];
}
// La empresa también va en las notas: si el contacto ya existía, su ficha no se toca y es
// el único sitio donde queda lo que dijo en el formulario.
const notas = [
  'Reservada desde la web.',
  v.empresa ? 'Empresa: ' + v.empresa : '',
  v.mensaje ? 'Qué quiere resolver: ' + v.mensaje : '',
].filter(Boolean).join('\n');
return [{ json: { _reservar: true, service_id: s.id, cita, notas, fecha: dt.toFormat('yyyy-LL-dd') } }];

// La respuesta de 22 -> contrato público. Por nombre de nodo, no por $json de nadie más.
const p = $('Code · Preparar').first().json;
const r = $json ?? {};
if (r.ok === true) {
  const ya = String(r.message || '').includes('idempotente');
  const cita_id = (r.data && r.data.appointment && r.data.appointment.id) || null;
  // Solo se invita en una reserva NUEVA: un reintento o un doble clic ya tuvo la suya.
  return [{ json: { _conflicto: false, _http: 200, _invitar: !ya && !!cita_id,
    cita_id, contact_id: r.contact_id || null,
    body: { ok: true, motivo: ya ? 'ya_estaba_reservada' : 'reservada', cita: p.cita } } }];
}
const st = String(r.status || r.error || '');
if (['slot_taken', 'slot_conflict', 'no_free_resource'].includes(st)) {
  return [{ json: { _conflicto: true, fecha: p.fecha, service_id: p.service_id } }];
}
return [{ json: { _conflicto: false, _http: 500, body: { ok: false, motivo: 'error' },
  _status_origen: st || null, _detalle: r.message || null } }];

// El hueco se llenó entre consultar y reservar: se devuelven los que quedan ese día para
// que la web ofrezca otro sin volver a pedir los datos.
const tz = $('Code · Validar').first().json.tz;
const r = $json ?? {};
const b = r.body || {};
const huecos_del_dia = ((r.statusCode ?? 0) < 300 && b.ok === true ? (b.slots || []) : []).map(s => ({
  inicio: s.start_at,
  hora: DateTime.fromISO(s.start_at, { setZone: true }).setZone(tz).toFormat('HH:mm'),
  plazas: s.seats_left,
}));
return [{ json: { _http: 409, body: { ok: false, motivo: 'hueco_no_disponible', huecos_del_dia } } }];
